"use client";

import { useState, useEffect, useMemo, useCallback } from "react";
import { showToast } from "@/components/ToastNotification";
import {
  Box,
  Button,
  Chip,
  Collapse,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  IconButton,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TableSortLabel,
  TextField,
  Typography,
} from "@mui/material";
import { MoreVert, SwapHoriz } from "@mui/icons-material";
import {
  getTransferListAction,
  createTransferAction,
  updateTransferAction,
  deleteTransferAction,
} from "@/features/transfer/actions";
import { getAccountsAction } from "@/features/account/actions";
import {
  cellSx,
  headCellSx,
  inputSx,
  formatIDR,
  sortLabelSx,
  tableRowSx,
  tablePaperSx,
  popperStyles,
  dialogPaperSx,
  dialogTitleSx,
  dialogContentSx,
  dialogActionsSx,
  cancelBtnSx,
  saveBtnSx,
} from "@/lib/theme-shared";
import TableFilter from "@/components/TableFilter";
import PageHeader from "@/components/PageHeader";
import SummaryCards from "@/components/SummaryCards";
import DataTableToolbar from "@/components/DataTableToolbar";
import ActionMenu from "@/components/ActionMenu";
import ConfirmDeleteDialog from "@/components/ConfirmDeleteDialog";
import StyledTablePagination from "@/components/StyledTablePagination";
import TableSkeletonRows from "@/components/TableSkeletonRows";
import EmptyTableRow from "@/components/EmptyTableRow";
import { useDataRefresh } from "@/hooks/useDataRefresh";
import { useQueryParams, readQueryParams } from "@/hooks/useQueryParams";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { AdapterDateFns } from "@mui/x-date-pickers/AdapterDateFns";
import { DatePicker } from "@mui/x-date-pickers/DatePicker";
import { parseISO, format } from "date-fns";
import type { TransferRow } from "@/types/transaction.type";

const COLUMNS = [
  { id: "id" as const, label: "ID" },
  { id: "tanggal" as const, label: "Tanggal" },
  { id: "akunAsal" as const, label: "Asal" },
  { id: "akunTujuan" as const, label: "Tujuan" },
  { id: "nominal" as const, label: "Nominal" },
  { id: "biaya" as const, label: "Biaya" },
  { id: "catatan" as const, label: "Catatan" },
];

const SKELETON_WIDTHS = [50, 80, 80, 80, 60, 50, 100, 40];

// ─── Component ────────────────────────────────────────────────────────────────
export default function TransferPage() {
  const [rows, setRows] = useState<TransferRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [accounts, setAccounts] = useState<{ id: number; name: string }[]>([]);

  const accountMap = useMemo(() => Object.fromEntries(accounts.map((a) => [a.id, a.name])), [accounts]);

  const [search, setSearch] = useState("");
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [orderBy, setOrderBy] = useState<keyof TransferRow>("tanggal");
  const [order, setOrder] = useState<"asc" | "desc">("desc");
  const [actionAnchor, setActionAnchor] = useState<{ el: HTMLElement; row: TransferRow } | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [rowToDelete, setRowToDelete] = useState<TransferRow | null>(null);
  const [formOpen, setFormOpen] = useState(false);
  const [editRow, setEditRow] = useState<TransferRow | null>(null);

  const [activeFilters, setActiveFilters] = useState<Record<string, string | number>>({ fromAccountId: "", toAccountId: "" });
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [filterOpen, setFilterOpen] = useState(false);

  const [form, setForm] = useState<any>({
    tanggal: new Date().toISOString().split("T")[0],
    fromAccountId: 0,
    toAccountId: 0,
    amount: "",
    feeFixed: "",
    feePercent: "",
    note: "",
  });

  // ─── Data Loading ─────────────────────────────────────────────────────────
  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      const [accRes, rowsRes] = await Promise.all([
        getAccountsAction(),
        getTransferListAction({ page: 1, pageSize: 100 }),
      ]);

      let currentAccounts: any[] = [];
      if (accRes.success) { setAccounts(accRes.data as any[]); currentAccounts = accRes.data; }

      const currentAccountMap = Object.fromEntries(currentAccounts.map((a: any) => [a.id, a.name]));

      if (rowsRes.success) {
        const items = rowsRes.data.items as any[];
        setRows(
          items.map((t) => ({
            id: `TRF-${String(t.id).padStart(3, '0')}`,
            tanggal: t.date,
            akunAsal: currentAccountMap[t.fromAccountId] || '',
            akunTujuan: currentAccountMap[t.toAccountId] || '',
            nominal: Number(t.amount) || 0,
            biaya: Number(t.feeAmount) || 0,
            catatan: t.note || '',
            raw: t,
          }))
        );
      }
    } catch (err) {
      console.error('failed to load transfer data', err);
    } finally {
      setLoading(false);
    }
  }, []);

  const loadRows = useCallback(async () => {
    try {
      setLoading(true);
      const json = await getTransferListAction({ page: 1, pageSize: 100 });
      if (json.success) {
        setRows(
          (json.data.items as any[]).map((t) => ({
            id: `TRF-${String(t.id).padStart(3, '0')}`,
            tanggal: t.date,
            akunAsal: accountMap[t.fromAccountId] || '',
            akunTujuan: accountMap[t.toAccountId] || '',
            nominal: Number(t.amount) || 0,
            biaya: Number(t.feeAmount) || 0,
            catatan: t.note || '',
            raw: t,
          }))
        );
      }
    } catch (err) {
      console.error('failed to load transfers', err);
    } finally {
      setLoading(false);
    }
  }, [accountMap]);

  useEffect(() => { loadData(); }, [loadData]);
  useDataRefresh(loadData);

  // ─── URL Sync ─────────────────────────────────────────────────────────────
  useEffect(() => {
    if (typeof window === "undefined") return;
    const params = readQueryParams();
    const urlSearch = params.get("search") || "";
    const urlFrom = params.get("fromAccountId") ? Number(params.get("fromAccountId")) || params.get("fromAccountId")! : "";
    const urlTo = params.get("toAccountId") ? Number(params.get("toAccountId")) || params.get("toAccountId")! : "";
    const urlStart = params.get("startDate") || "";
    const urlEnd = params.get("endDate") || "";

    if (urlSearch) setSearch(urlSearch);
    if (urlFrom || urlTo) { setActiveFilters({ fromAccountId: urlFrom, toAccountId: urlTo }); setFilterOpen(true); }
    if (urlStart) { setStartDate(urlStart); setFilterOpen(true); }
    if (urlEnd) { setEndDate(urlEnd); setFilterOpen(true); }
  }, []);

  useQueryParams({
    search,
    ...(activeFilters.fromAccountId ? { fromAccountId: String(activeFilters.fromAccountId) } : {}),
    ...(activeFilters.toAccountId ? { toAccountId: String(activeFilters.toAccountId) } : {}),
    ...(startDate ? { startDate } : {}),
    ...(endDate ? { endDate } : {}),
  });

  // ─── Filtering & Sorting ─────────────────────────────────────────────────
  const filtered = rows
    .filter((r) => {
      const q = search.toLowerCase();
      const matchesSearch = r.id.toLowerCase().includes(q) || r.akunAsal.toLowerCase().includes(q) || r.akunTujuan.toLowerCase().includes(q) || r.catatan.toLowerCase().includes(q);
      if (!matchesSearch) return false;
      if (activeFilters.fromAccountId && r.raw?.fromAccountId !== activeFilters.fromAccountId) return false;
      if (activeFilters.toAccountId && r.raw?.toAccountId !== activeFilters.toAccountId) return false;
      if (startDate && new Date(r.tanggal) < new Date(startDate)) return false;
      if (endDate && new Date(r.tanggal) > new Date(endDate)) return false;
      return true;
    })
    .sort((a, b) => {
      const av = a[orderBy], bv = b[orderBy];
      if (av < bv) return order === "asc" ? -1 : 1;
      if (av > bv) return order === "asc" ? 1 : -1;
      return 0;
    });

  const paginated = filtered.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage);
  const totalNominal = filtered.reduce((s, r) => s + r.nominal, 0);
  const totalBiaya = filtered.reduce((s, r) => s + r.biaya, 0);

  const handleSort = (col: keyof TransferRow) => {
    if (orderBy === col) setOrder(order === "asc" ? "desc" : "asc");
    else { setOrderBy(col); setOrder("asc"); }
    setPage(0);
  };

  // ─── CRUD Handlers ────────────────────────────────────────────────────────
  const handleDelete = async () => {
    if (!rowToDelete) return;
    try {
      const idNum = parseInt(rowToDelete.id.replace(/^TRF-/, ''), 10);
      await deleteTransferAction(idNum);
      showToast("Transfer berhasil dihapus!", "success");
      loadRows();
    } catch (err) {
      console.error('delete error', err);
      showToast("Gagal menghapus data transfer.", "error");
    }
    setDeleteDialogOpen(false);
    setActionAnchor(null);
  };

  const openAdd = () => {
    setEditRow(null);
    setForm({ tanggal: new Date().toISOString().split("T")[0], fromAccountId: accounts[0]?.id || 0, toAccountId: accounts[1]?.id || 0, amount: "", feeFixed: "", feePercent: "", note: "" });
    setFormOpen(true);
  };

  const openEdit = (row: TransferRow) => {
    setEditRow(row);
    const raw = row.raw;
    setForm({ tanggal: raw.date, fromAccountId: raw.fromAccountId, toAccountId: raw.toAccountId, amount: String(raw.amount), feeFixed: String(raw.feeFixed || ""), feePercent: String(raw.feePercent || ""), note: raw.note || "" });
    setFormOpen(true);
    setActionAnchor(null);
  };

  const handleSave = async () => {
    if (!form.amount) return;
    try {
      const payload = {
        date: form.tanggal,
        fromAccountId: form.fromAccountId,
        toAccountId: form.toAccountId,
        amount: Number(form.amount),
        feeFixed: form.feeFixed ? Number(form.feeFixed) : undefined,
        feePercent: form.feePercent ? Number(form.feePercent) : undefined,
        note: form.note,
      };

      if (editRow) {
        await updateTransferAction({
          id: parseInt(editRow.id.replace(/^TRF-/, ''), 10),
          ...payload,
        });
      } else {
        await createTransferAction(payload);
      }
      showToast(editRow ? "Transfer berhasil diperbarui!" : "Transfer berhasil ditambahkan!", "success");
      await loadRows();
    } catch (err) {
      console.error('save error', err);
      showToast("Gagal menyimpan data transfer.", "error");
    }
    setFormOpen(false);
  };

  const hasActiveFilters = Object.values(activeFilters).some((v) => v !== "") || !!startDate || !!endDate;

  return (
    <Box sx={{ p: { xs: 3, md: 4 }, minHeight: "100vh" }}>
      <PageHeader title="Transfer" subtitle="Kelola perpindahan dana antar akun" icon={<SwapHoriz sx={{ fontSize: 18, color: "#06b6d4" }} />} iconBgColor="rgba(6,182,212,0.12)" />

      <SummaryCards cards={[
        { label: "Total Transfer", value: formatIDR(rows.reduce((s, r) => s + r.nominal, 0)), sub: `${rows.length} transaksi`, color: "#06b6d4" },
        { label: "Total Biaya", value: formatIDR(rows.reduce((s, r) => s + r.biaya, 0)), sub: "Admin + biaya", color: "#f59e0b" },
        { label: "Rata-rata Transfer", value: formatIDR(rows.length > 0 ? rows.reduce((s, r) => s + r.nominal, 0) / rows.length : 0), sub: "Per transaksi", color: "#06b6d4" },
      ]} />

      <Paper elevation={0} sx={tablePaperSx}>
        <DataTableToolbar
          search={search} onSearchChange={(v) => { setSearch(v); setPage(0); }}
          resultCount={filtered.length} resultTotal={formatIDR(totalNominal)}
          filterOpen={filterOpen} onFilterToggle={() => setFilterOpen(!filterOpen)}
          onResetFilters={() => { setActiveFilters({ fromAccountId: "", toAccountId: "" }); setStartDate(""); setEndDate(""); }}
          hasActiveFilters={hasActiveFilters} onAdd={openAdd} searchPlaceholder="Cari transfer..."
        />

        <Collapse in={filterOpen}>
          <Box sx={{ px: 3, pb: 2 }}>
            <TableFilter
              options={[
                { key: "fromAccountId", label: "Akun Asal", options: accounts.map((a) => ({ id: a.id, name: a.name })) },
                { key: "toAccountId", label: "Akun Tujuan", options: accounts.map((a) => ({ id: a.id, name: a.name })) },
              ]}
              activeFilters={activeFilters}
              onFilterChange={(key, val) => setActiveFilters((prev) => ({ ...prev, [key]: val }))}
              startDate={startDate} endDate={endDate} onStartDateChange={setStartDate} onEndDateChange={setEndDate}
            />
          </Box>
        </Collapse>

        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                {COLUMNS.map((col) => (
                  <TableCell key={col.id} sx={headCellSx}>
                    <TableSortLabel active={orderBy === col.id} direction={orderBy === col.id ? order : "asc"} onClick={() => handleSort(col.id)} sx={sortLabelSx}>{col.label}</TableSortLabel>
                  </TableCell>
                ))}
                <TableCell sx={{ ...headCellSx, textAlign: "center" }}>Aksi</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableSkeletonRows columns={SKELETON_WIDTHS} />
              ) : paginated.length === 0 ? (
                <EmptyTableRow colSpan={8} />
              ) : (
                paginated.map((row, i) => (
                  <TableRow key={row.id} sx={tableRowSx(i)}>
                    <TableCell sx={{ ...cellSx, color: "#6366f1", fontWeight: 600, fontFamily: "monospace", fontSize: "0.75rem" }}>{row.id}</TableCell>
                    <TableCell sx={cellSx}>{new Date(row.tanggal).toLocaleDateString("id-ID", { day: "2-digit", month: "short", year: "numeric" })}</TableCell>
                    <TableCell sx={cellSx}>
                      <Chip label={row.akunAsal} size="small" variant="filled" sx={{ fontSize: "0.6875rem", height: 22, fontWeight: 600, borderRadius: "6px", backgroundColor: "rgba(239,68,68,0.12)", color: "#fca5a5" }} />
                    </TableCell>
                    <TableCell sx={cellSx}>
                      <Chip label={row.akunTujuan} size="small" variant="filled" sx={{ fontSize: "0.6875rem", height: 22, fontWeight: 600, borderRadius: "6px", backgroundColor: "rgba(34,197,94,0.12)", color: "#86efac" }} />
                    </TableCell>
                    <TableCell sx={{ ...cellSx, color: "#06b6d4", fontWeight: 600, whiteSpace: "nowrap" }}>{formatIDR(row.nominal)}</TableCell>
                    <TableCell sx={{ ...cellSx, color: row.biaya > 0 ? "#f59e0b" : "#334155", fontWeight: 500, whiteSpace: "nowrap" }}>{row.biaya > 0 ? formatIDR(row.biaya) : "—"}</TableCell>
                    <TableCell sx={{ ...cellSx, color: "#64748b", maxWidth: 200, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{row.catatan || "—"}</TableCell>
                    <TableCell sx={{ ...cellSx, textAlign: "center" }}>
                      <IconButton size="small" onClick={(e) => setActionAnchor({ el: e.currentTarget, row })} sx={{ color: "#475569", "&:hover": { color: "#c7d2fe", bgcolor: "rgba(99,102,241,0.1)" } }}><MoreVert fontSize="small" /></IconButton>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>

        <StyledTablePagination count={filtered.length} page={page} rowsPerPage={rowsPerPage} onPageChange={(_, p) => setPage(p)} onRowsPerPageChange={(e) => { setRowsPerPage(parseInt(e.target.value, 10)); setPage(0); }} />
      </Paper>

      <ActionMenu anchorEl={actionAnchor?.el ?? null} open={Boolean(actionAnchor)} onClose={() => setActionAnchor(null)} onEdit={() => { if (actionAnchor) openEdit(actionAnchor.row); }} onDelete={() => { if (actionAnchor) { setRowToDelete(actionAnchor.row); setDeleteDialogOpen(true); } }} />

      <Dialog open={formOpen} onClose={() => setFormOpen(false)} PaperProps={dialogPaperSx}>
        <DialogTitle sx={dialogTitleSx}>{editRow ? "Edit Transfer" : "Tambah Transfer"}</DialogTitle>
        <DialogContent sx={dialogContentSx}>
          <LocalizationProvider dateAdapter={AdapterDateFns}>
            <DatePicker label="Tanggal" value={form.tanggal ? parseISO(form.tanggal) : null} onChange={(newVal) => { if (newVal) setForm({ ...form, tanggal: format(newVal as Date, "yyyy-MM-dd") }); }}
              slotProps={{ textField: { size: "small", fullWidth: true }, popper: { sx: popperStyles } }} />
          </LocalizationProvider>
          <FormControl size="small" fullWidth><InputLabel sx={{ color: "#64748b" }}>Akun Asal</InputLabel><Select value={form.fromAccountId} label="Akun Asal" onChange={(e) => setForm({ ...form, fromAccountId: Number(e.target.value) })} sx={inputSx}>{accounts.map((a) => <MenuItem key={a.id} value={a.id}>{a.name}</MenuItem>)}</Select></FormControl>
          <FormControl size="small" fullWidth><InputLabel sx={{ color: "#64748b" }}>Akun Tujuan</InputLabel><Select value={form.toAccountId} label="Akun Tujuan" onChange={(e) => setForm({ ...form, toAccountId: Number(e.target.value) })} sx={inputSx}>{accounts.map((a) => <MenuItem key={a.id} value={a.id}>{a.name}</MenuItem>)}</Select></FormControl>
          <TextField label="Nominal (IDR)" size="small" fullWidth type="number" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} InputLabelProps={{ sx: { color: "#64748b" } }} InputProps={{ sx: inputSx }} />
          <Box sx={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 2 }}>
            <TextField label="Biaya Tetap" size="small" fullWidth type="number" value={form.feeFixed} onChange={(e) => setForm({ ...form, feeFixed: e.target.value })} InputLabelProps={{ sx: { color: "#64748b" } }} InputProps={{ sx: inputSx }} />
            <TextField label="Biaya (%)" size="small" fullWidth type="number" value={form.feePercent} onChange={(e) => setForm({ ...form, feePercent: e.target.value })} InputLabelProps={{ sx: { color: "#64748b" } }} InputProps={{ sx: inputSx }} />
          </Box>
          <TextField label="Catatan" size="small" fullWidth multiline rows={2} value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} InputLabelProps={{ sx: { color: "#64748b" } }} InputProps={{ sx: inputSx }} />
        </DialogContent>
        <DialogActions sx={dialogActionsSx}>
          <Button onClick={() => setFormOpen(false)} size="small" sx={cancelBtnSx}>Batal</Button>
          <Button onClick={handleSave} size="small" variant="contained" sx={saveBtnSx}>{editRow ? "Simpan" : "Tambah"}</Button>
        </DialogActions>
      </Dialog>

      <ConfirmDeleteDialog open={deleteDialogOpen} onClose={() => setDeleteDialogOpen(false)} onConfirm={handleDelete} itemId={rowToDelete?.id} />
    </Box>
  );
}